 "code": {
 "engine": "trino",
 "version": "386",
 "body": "with inputs as( select block_height, tx_id, array_join(witness_data,',') payload from bitcoin.inputs t where t.block_height>=792945 and t.block_height<799945 and t.index=0), txns as ( select t.id txid, t.index from bitcoin.transactions t where t.block_height>=792945 and t.block_height<799945 ), rawdata as ( SELECT '{' || from_utf8( from_hex( substr( payload, position('2270223a226272632d3230' in payload), position('7d68' in payload) - position('2270223a226272632d3230' in payload) ) ) ) || '}' as body, block_height, t.tx_id as txid FROM inputs t WHERE 1=1 AND t.payload LIKE '%0063036f726401%' AND t.payload LIKE '%2270223a226272632d3230%' AND t.payload LIKE '%227469636b223a226473726322%' ), formatted as ( select *, COALESCE(TRY(JSON_PARSE(body)), NULL) as data from rawdata ), parsed as ( SELECT t.txid, block_height, json_extract_scalar(t.data, '$.p') as p, json_extract_scalar(t.data, '$.tick') as tick, json_extract_scalar(t.data, '$.op') as op, COALESCE( TRY( CAST (json_extract_scalar(t.data, '$.amt') AS integer) ), 0 ) as amt FROM formatted t where t.data is not null ), filtered as ( select * from parsed t where (t.p='brc-20' or t.p='brc-20c') and t.tick='dsrc' and t.op='mint' and t.amt>0 and t.amt<=1000 ), integrated as ( select t.*, f.index from filtered t join txns f on t.txid=f.txid ), sequenced as ( select row_number() OVER (ORDER BY t.block_height ASC,t.index ASC) as seq, t.* from integrated t ), decodes as ( select * from sequenced order by seq asc ), temp1 as ( select ROW_NUMBER() OVER (PARTITION BY block_height/10 ORDER BY seq ASC) emission, * from decodes t where t.block_height>=792945 AND t.amt<=CASE WHEN 1000/POWER(2,(block_height-792945)/144) > 125 THEN 1000/POWER(2,(block_height-792945)/144) ELSE 125 END ), temp2 as ( select SUM(t.amt) over (order by seq) as supply, * from temp1 t where t.emission<=100 order by seq ASC ), dsrc as ( select * from temp2 t where t.supply<2100*10000 )"
 },
 "oops": {
 "mint": "select * from dsrc"
 }
}

